/* M109 – Zutritt und Datenschutz – version allemande, générée par outils/traduction.js depuis data.js (mêmes épreuves, même ordre). a[0] = richtige Antwort. */
window.OBJ = [{"code":"A2.2","t":"Zutrittsberechtigungen","g":"Ich erkläre das Prinzip der Zutrittsberechtigungen zu Gebäuden und Anlagen sowie der Zugriffsrechte auf Anwendungen und beschreibe die Systeme, mit denen mein Betrieb diese Berechtigungen und Rechte durchsetzt. (K2)","col":"teal","ic":"badge","ch":[{"k":"qcm","q":"Nach welchem Kriterium werden Schlüssel oder Badges in einem Betrieb verteilt?","a":["Nach der Verantwortung jeder Person","Nach den Dienstjahren im Betrieb","Für alle Mitarbeitenden gleich","Nach dem persönlichen Wunsch jeder Person"],"ex":"Jede Mitarbeiterin und jeder Mitarbeiter erhält einen bestimmten Zutritt zu den Räumen: Schlüssel oder Badges werden nach Verantwortung verteilt.","ref":"Lektion 9.1"},{"k":"tf","q":"Sie dürfen Ihren Badge einem vertrauenswürdigen Kollegen ausleihen, ohne um Erlaubnis zu fragen.","v":false,"ex":"Regel Nr. 1: Schlüssel oder Badge nie ohne Erlaubnis jemand anderem überlassen.","ref":"Lektion 9.1"},{"k":"multi","q":"Welche Regeln für Schlüssel und Badges stehen im Kurs?","good":["Den Schlüssel nie ohne Erlaubnis weitergeben","Den Schlüssel sicher aufbewahren, wenn er nicht gebraucht wird","Den Schlüssel nie an der Tür stecken lassen","Den Betrieb nicht auf dem Schlüssel angeben"],"bad":["Einen Zweitschlüssel unter der Fussmatte verstecken","Die Adresse des Lagers auf den Schlüsselanhänger schreiben"],"ex":"Der Kurs nennt fünf Regeln: nicht weitergeben, sicher aufbewahren, nicht an der Tür stecken lassen, kein offensichtliches Versteck (Fussmatte), keine Angabe des Betriebs.","ref":"Lektion 9.1"},{"k":"tf","q":"Es ist ratsam, den Namen des Betriebs auf den Schlüssel zu schreiben, damit er bei Verlust zurückgebracht werden kann.","v":false,"ex":"Aus Sicherheitsgründen darf der Betrieb auf dem Schlüssel nicht erkennbar sein: Wer ihn findet, wüsste, wo er passt.","ref":"Lektion 9.1"},{"k":"qcm","q":"Was müssen Sie tun, wenn Sie einen Schlüssel des Betriebs verlieren?","a":["Es sofort dem Arbeitgeber melden","Einige Tage warten, bis er wieder auftaucht","Auf eigene Kosten eine Kopie machen lassen und nichts sagen","Bis dahin den Schlüssel eines Kollegen ausleihen"],"ex":"Ein Verlust muss sofort dem Arbeitgeber gemeldet werden, damit er vorbeugende Massnahmen treffen kann.","ref":"Lektion 9.1"},{"k":"qcm","q":"Warum kann der Verlust eines mechanischen Schlüssels teuer werden?","a":["Man muss manchmal alle Schlösser ersetzen, die er öffnet","Der Schlüssel selbst ist aus einem Edelmetall gefertigt","Die Versicherung deckt die Mitarbeiterin nie","Der Betrieb muss schliessen, bis man ihn wiederfindet"],"ex":"Ein verlorener Schlüssel kann den Ersatz aller Schlösser nötig machen, die er öffnet.","ref":"Lektion 9.1"},{"k":"fill","q":"Ein verlorener elektronischer Schlüssel kann ___ werden, was den Ersatz der Schlösser vermeidet.","a":["deaktiviert","dupliziert","graviert","ausgeliehen"],"ex":"Bei modernen Systemen wird der elektronische Schlüssel deaktiviert: kein Schlosswechsel, aber andere Kosten.","ref":"Lektion 9.1"},{"k":"tf","q":"Einen verlorenen elektronischen Badge zu deaktivieren, verursacht dem Betrieb keine Kosten.","v":false,"ex":"Die Deaktivierung vermeidet den Ersatz der Schlösser, verursacht aber andere Kosten (neuer Badge, Verwaltung des Systems).","ref":"Lektion 9.1"},{"k":"qcm","q":"Womit beginnt der Zugang zum Informatiksystem des Betriebs in der Regel?","a":["Mit einem Benutzernamen und einem Passwort","Mit dem Vorzeigen des Badges beim Chef","Mit einer Unterschrift in einem Papierregister","Allein mit der E-Mail-Adresse des Betriebs"],"ex":"Der Zugang zum Informatiksystem beginnt in der Regel mit einem Benutzernamen und einem Passwort.","ref":"Lektion 9.5"},{"k":"qcm","q":"Warum zeichnet das Informatiksystem jeden Zugriff auf?","a":["Um jedes unbefugte Eindringen zu erkennen","Um den Lohn jeder Person zu berechnen","Um die Anmeldung der Benutzer zu beschleunigen","Um die Tätigkeit jeder Person zu veröffentlichen"],"ex":"Das System zeichnet jeden Zugriff auf, um jedes unbefugte Eindringen zu erkennen.","ref":"Lektion 9.5"},{"k":"fill","q":"Die Zugriffsrechte auf Anwendungen werden nach den ___ der Mitarbeitenden vergeben.","a":["Verantwortlichkeiten","Vorlieben","Altersstufen","Arbeitszeiten"],"ex":"Wie bei den Schlüsseln richten sich die Informatik-Zugriffsrechte nach der Verantwortung jeder Person.","ref":"Lektion 9.5"},{"k":"qcm","q":"Wer betreut in der Regel die Netzwerke und Informatiksysteme des Betriebs?","a":["Die Systemadministratoren","Die Logistiker an der Rampe","Die Kunden des Betriebs","Die Lieferanten der Geräte"],"ex":"Die Systemadministratoren betreuen die Netzwerke; alle Mitarbeitenden müssen jedoch die Regeln einhalten.","ref":"Lektion 9.5"},{"k":"tf","q":"Da die Systemadministratoren die Informatik betreuen, müssen Logistiker/-innen keine Regeln einhalten.","v":false,"ex":"Alle Mitarbeitenden, auch die Logistiker/-innen, müssen die festgelegten Regeln einhalten.","ref":"Lektion 9.5"},{"k":"match","q":"Ordnen Sie jedem Mittel zu, was es kontrolliert.","p":[["Schlüssel oder Badge","Der Zutritt zu Räumen und Anlagen"],["Benutzername und Passwort","Der Zugang zum Informatiksystem"],["Zugriffsrechte","Die je nach Funktion nutzbaren Anwendungen"],["Zugriffsprotokoll","Das Erkennen von Eindringlingen"]],"ex":"Physischer Zutritt (Schlüssel, Badges) und Informatikzugriff (Benutzername, Rechte, Protokoll) folgen derselben Logik.","ref":"Lektionen 9.1 und 9.5"},{"k":"sort","q":"Zutritt zu Räumen oder Zugriff auf Anwendungen? Ordnen Sie zu.","c":["Zutritt zu Räumen","Zugriff auf Anwendungen"],"it":[["Elektronischer Badge",0],["Schlüssel der Lagertür",0],["Passwort",1],["Vom Administrator vergebene Rechte",1],["Schloss des Lagerraums",0],["Benutzername",1]],"ex":"Schlüssel, Badges und Schlösser schützen die Gebäude; Benutzernamen, Passwörter und Rechte schützen die Anwendungen.","ref":"Lektionen 9.1 und 9.5"},{"k":"order","q":"Sie verlieren Ihren elektronischen Badge. Bringen Sie die Schritte in die richtige Reihenfolge.","a":["Den Verlust des Badges feststellen","Den Verlust dem Arbeitgeber melden","Deaktivierung des verlorenen Badges","Abgabe eines neuen Badges"],"ex":"Eine sofortige Meldung erlaubt dem Arbeitgeber, den Badge zu deaktivieren, bevor ihn eine Drittperson benutzt.","ref":"Lektion 9.1"},{"k":"odd","q":"Finden Sie den Ausreisser: Diese Verhaltensweisen halten die Schlüsselregeln ein, ausser einer.","a":["Den Schlüssel an der Tür des Raums stecken lassen","Den Schlüssel an einem sicheren Ort aufbewahren","Einen verlorenen Schlüssel sofort melden","Den Schlüssel ohne Erlaubnis nicht ausleihen"],"ex":"Ein Schlüssel darf nie an der Tür stecken bleiben.","ref":"Lektion 9.1"},{"k":"case","s":"Ein externer Lieferant bittet Sie um Ihren Badge, um im Lager einen Handhubwagen zu holen, während Sie seinen Lastwagen entladen.","q":"Was tun Sie?","a":["Sie lehnen ab und rufen eine verantwortliche Person","Sie leihen ihm den Badge, wenn er ihn schnell zurückgibt","Sie geben ihm lieber den Code der Tür","Sie lassen die Tür offen, um Zeit zu sparen"],"ex":"Der Badge wird nie ohne Erlaubnis weitergegeben: Der Zutritt der externen Person muss kontrolliert werden.","ref":"Lektion 9.1"},{"k":"case","s":"Am Feierabend lässt ein Kollege den Schlüsselbund des Lagers im Schloss stecken, «für das Frühteam».","q":"Was ist das Problem?","a":["Jeder kann hinein: Ein Schlüssel bleibt nie an der Tür","Keines, wenn das Frühteam vor allen anderen kommt","Der Schlüsselbund kann sich höchstens abnutzen oder verbiegen","Man hätte ihn besser unter der Fussmatte am Eingang versteckt"],"ex":"Nie einen Schlüssel an der Tür stecken lassen, auch nicht an einem offensichtlichen Ort wie unter der Fussmatte.","ref":"Lektion 9.1"},{"k":"case","s":"Am Montagmorgen stellen Sie fest, dass der Schlüssel zum Raum für Wertwaren seit Freitag fehlt. Sie denken, ihn heute Abend zu Hause zu finden.","q":"Welche Haltung ist richtig?","a":["Den Verlust sofort dem Arbeitgeber melden","Zuerst zu Hause suchen und morgen darüber reden","Bis dahin den Schlüssel eines Kollegen ausleihen","Nichts sagen, solange nichts gestohlen wurde"],"ex":"Ein Verlust wird sofort gemeldet: Der Arbeitgeber muss ohne Verzögerung vorbeugende Massnahmen treffen können.","ref":"Lektion 9.1"},{"k":"case","s":"Ihr Betrieb hat mechanische Schlösser. Ein Lernender hat den Passepartout verloren, der alle Räume öffnet.","q":"Welche finanzielle Folge ist wahrscheinlich?","a":["Alle Schlösser ersetzen, die dieser Passepartout öffnet","Nur das Schloss des Büros des Lernenden ersetzen","Keine, es genügt, eine Kopie des Schlüssels zu machen","Den Schlüssel aus der Ferne kostenlos deaktivieren"],"ex":"Ein mechanischer Schlüssel lässt sich nicht deaktivieren: Alle Schlösser, die er öffnet, müssen eventuell ersetzt werden.","ref":"Lektion 9.1"},{"k":"case","s":"Der Betrieb hat auf elektronische Badges umgestellt. Eine Kollegin hat ihren im Bus verloren.","q":"Welcher Vorteil des modernen Systems gilt hier?","a":["Er lässt sich ohne Schlosswechsel deaktivieren","Der Badge zerstört sich ausserhalb des Betriebs von selbst","Ein verlorener Badge kostet nie jemandem etwas","Der Badge bleibt gültig, keine Massnahme ist nötig"],"ex":"Elektronische Schlüssel lassen sich deaktivieren, was den Ersatz der Schlösser vermeidet (aber andere Kosten verursacht).","ref":"Lektion 9.1"},{"k":"case","s":"Ein neuer Logistiker stellt fest, dass er das Buchhaltungsmodul der Lagerverwaltungssoftware nicht öffnen kann, seine Chefin aber schon.","q":"Wie lässt sich das erklären?","a":["Die Zugriffsrechte hängen von der Verantwortung ab","Sein Konto wurde sicher gehackt","Die Software ist älteren Mitarbeitenden vorbehalten","Er muss das Passwort seiner Chefin verwenden"],"ex":"Die Zugriffsrechte werden nach der Verantwortung jeder Person vergeben.","ref":"Lektion 9.5"},{"k":"case","s":"Ihr abwesender Teamleiter bittet Sie am Telefon, sich mit seinem Benutzernamen anzumelden, um eine dringende Bestellung freizugeben.","q":"Welche Antwort ist am professionellsten?","a":["Ablehnen und verlangen, dass Ihnen die nötigen Rechte erteilt werden","Annehmen, da es Ihr direkter Vorgesetzter verlangt","Annehmen und sein Passwort für das nächste Mal notieren","Mit Ihrem eigenen Konto freigeben und die Kontrolle umgehen"],"ex":"Alle arbeiten mit ihren eigenen Rechten: Das Konto eines anderen zu nutzen, verfälscht das Zugriffsprotokoll und umgeht die Berechtigungen.","ref":"Lektion 9.5"},{"k":"case","s":"Die Informatik meldet mehrere Anmeldeversuche mit Ihrem Benutzernamen um 3 Uhr morgens.","q":"Wodurch wurden diese Versuche erkannt?","a":["Das System zeichnet jeden Zugriff auf","Kollegen überwachen nachts die Bildschirme","Das Passwort schickt dem Direktor ein SMS","Der Eingangsbadge sperrt den Computer"],"ex":"Jeder Zugriff wird aufgezeichnet, was das Erkennen eines unbefugten Eindringens erlaubt.","ref":"Lektion 9.5"},{"k":"case","s":"Eine unbekannte Person in Arbeitsweste folgt Ihnen dicht, um durch die gesicherte Tür zu gelangen, die Sie gerade mit Ihrem Badge geöffnet haben.","q":"Was tun Sie?","a":["Sie höflich nach ihrem Badge fragen oder zum Empfang schicken","Sie durchlassen, da sie eine Weste des Betriebs trägt","Ihr die Tür aufhalten, um freundlich und schnell zu sein","Ihr Ihren Badge leihen, damit sie sich allein bewegen kann"],"ex":"Jede Person muss mit ihrem eigenen Zutritt hinein; Besuchende gehen über den Empfang. (Gute Praxis, nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Zutrittskontrolle"},{"k":"case","s":"Ein Freund schlägt vor, «Logistik AG – Lager Nord» auf Ihren Schlüsselanhänger zu gravieren, damit Sie Ihre Schlüssel nicht mehr verwechseln.","q":"Warum lehnen Sie ab?","a":["Ein angeschriebener verlorener Schlüssel verrät, wo er passt","Die Gravur beschädigt den Schlüssel und blockiert das Schloss","Nur die verantwortliche Person darf auf einen Schlüssel schreiben","Ein gravierter Schlüssel ist nicht mehr versichert"],"ex":"Der Betrieb darf aus Sicherheitsgründen auf dem Schlüssel nicht erkennbar sein.","ref":"Lektion 9.1"},{"k":"case","s":"Sie verlassen den Betrieb Ende Monat. Sie haben noch einen Badge, zwei Schlüssel und Ihr Informatikkonto.","q":"Was muss geschehen?","a":["Alles zurückgeben und die Zugänge löschen lassen","Den Badge als Andenken behalten, er wird irgendwann deaktiviert","Die Schlüssel ohne Mitteilung der Nachfolgerin geben","Das Konto für alle Fälle aktiv lassen"],"ex":"Die Zugänge richten sich nach der Verantwortung: ohne Funktion keine Zugänge mehr. (Gute Praxis, nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Verwaltung der Zugänge"}]},{"code":"A2.3","t":"Informatiksicherheit","g":"Ich erkläre, wie ich die Informatikmittel systematisch nutze und wie ich den Betrieb vor Gefahren, insbesondere aus der Internetnutzung, schütze (Datensicherheit, Hackerangriffe, Viren, Phishing usw.). (K2)","col":"indigo","ic":"lock","ch":[{"k":"num","q":"Wie lang muss ein wirksames Passwort laut Kurs mindestens sein?","n":12,"tol":0,"u":"Zeichen","ex":"Der Kurs legt eine Mindestlänge von 12 Zeichen fest.","ref":"Lektion 9.5.1"},{"k":"num","q":"Wie oft sollte man laut Kurs das Passwort mindestens wechseln, alle wie viele Monate?","n":3,"tol":0,"u":"Monate","ex":"Der Kurs empfiehlt einen Wechsel mindestens alle drei Monate.","ref":"Lektion 9.5.1"},{"k":"multi","q":"Welche Regeln muss ein sicheres Passwort laut Kurs einhalten?","good":["Mindestens 12 Zeichen","Gross- und Kleinbuchstaben","Ziffern und Sonderzeichen","Ein eigenes Passwort pro Konto"],"bad":["Das Geburtsdatum enthalten","Auf allen Konten gleich sein"],"ex":"Keine persönlichen Angaben und für jedes Konto ein anderes Passwort.","ref":"Lektion 9.5.1"},{"k":"tf","q":"«Marie1990» ist ein gutes Passwort, weil es einen Grossbuchstaben, Kleinbuchstaben und Ziffern enthält.","v":false,"ex":"Es ist zu kurz (9 Zeichen) und enthält persönliche Angaben (Vorname, Jahr).","ref":"Lektion 9.5.1"},{"k":"qcm","q":"Welches dieser Passwörter hält die Regeln des Kurses am besten ein?","a":["T4p!s-Rouge#Quai27","qwertz12345678","Logistik2024!","Pierre-12.05.1998"],"ex":"Lang, gemischt und ohne Folge oder persönliche Angabe. «qwertz» ist eine vorhersehbare Folge, das Geburtsdatum ist persönlich.","ref":"Lektion 9.5.1"},{"k":"fill","q":"Für mehr Sicherheit aktivieren Sie die ___-Faktor-Authentifizierung.","a":["Zwei","Ein","Zehn","Null"],"ex":"Die Zwei-Faktor-Authentifizierung ergänzt das Passwort mit einem zweiten Nachweis.","ref":"Lektion 9.5.1"},{"k":"qcm","q":"Welches Hilfsmittel empfiehlt der Kurs, um eigene Passwörter zu verwalten?","a":["Einen Passwort-Manager","Ein Heft unter der Tastatur","Überall dasselbe Passwort","Eine Textdatei auf dem Desktop"],"ex":"Der Kurs empfiehlt einen Passwort-Manager (Vergleich als Link in der Lektion).","ref":"Lektion 9.5.1"},{"k":"match","q":"Ordnen Sie jedem Grund aus dem Kurs zu, was er verhindert.","p":[["Gegen Brute-Force","Den Code mit einem automatischen Programm erraten"],["Gegen Kontohacking","Verlust sensibler Daten eines kompromittierten Kontos"],["Eigenes Passwort","Dominoeffekt nach einem Datenleck einer Website"],["Gegen Identitätsdiebstahl","Missbräuchliche Nutzung Ihrer Angaben"]],"ex":"Der Kurs nennt vier Gründe, die Passwortregeln einzuhalten.","ref":"Lektion 9.5.1"},{"k":"qcm","q":"Was ist ein Brute-Force-Angriff?","a":["Automatisch sehr viele Kombinationen ausprobieren","Den Computer aufbrechen, um die Festplatte zu stehlen","Eine Mitarbeiterin bedrohen, damit sie ihren Code verrät","Den Strom des Servers abstellen, um den Betrieb zu blockieren"],"ex":"Angreifer nutzen automatisierte Methoden, um Zugangscodes zu erraten oder zu knacken.","ref":"Lektion 9.5.1"},{"k":"tf","q":"Dasselbe Passwort für mehrere Konten erhöht das Risiko bei einem Datenleck einer Website.","v":true,"ex":"Mit eigenen Passwörtern gefährdet ein Datenleck einer Website die anderen Konten nicht.","ref":"Lektion 9.5.1"},{"k":"odd","q":"Finden Sie den Ausreisser: Diese Praktiken stärken die Sicherheit, ausser einer.","a":["Überall die Folge «123456» verwenden","Die Zwei-Faktor-Authentifizierung aktivieren","Einen Passwort-Manager verwenden","Das Passwort regelmässig wechseln"],"ex":"Einfache oder vorhersehbare Folgen sind auszuschliessen.","ref":"Lektion 9.5.1"},{"k":"qcm","q":"Wozu dient eine Website wie haveibeenpwned.com, die in der Lektion genannt wird?","a":["Prüfen, ob Ihre E-Mail in einem Datenleck vorkommt","Eine anonyme E-Mail-Adresse für Online-Einkäufe erstellen","Automatisch alle Viren des Computers blockieren","Ihr Passwort regelmässig für Sie wechseln"],"ex":"Die Lektion stellt sie unter «Ist Ihre E-Mail in Gefahr?» vor.","ref":"Lektion 9.5 · nützliche Links"},{"k":"qcm","q":"Was stellt die Einhaltung der Passwortregeln laut Kurs sicher?","a":["Die Vertraulichkeit, Integrität und Verfügbarkeit der Daten","Die Geschwindigkeit des Netzwerks und der Drucker des Betriebs","Die Gratisnutzung aller im Betrieb verwendeten Programme","Das Löschen der im Alltag unnötig gewordenen Datensicherungen"],"ex":"Der Kurs schliesst: Vertraulichkeit, Integrität und Verfügbarkeit der Daten sowie Vertrauen der Benutzer.","ref":"Lektion 9.5.1"},{"k":"tf","q":"Die Zwei-Faktor-Authentifizierung verlangt zusätzlich zum Passwort einen zweiten Nachweis, zum Beispiel einen Code auf dem Handy.","v":true,"ex":"Auch wenn das Passwort gestohlen wird, kann sich der Hacker ohne den zweiten Faktor nicht anmelden.","ref":"Lektion 9.5.1"},{"k":"multi","q":"Welche Hinweise können auf ein Phishing-E-Mail deuten?","good":["Dringlichkeit oder Drohung, um Sie zu drängen","Ungewöhnliche Absenderadresse","Forderung nach Kreditkartendaten","Link zu einer Website mit seltsamem Namen"],"bad":["Erwartete Nachricht einer Kollegin, ohne Link oder Anhang"],"img":"mail","ex":"Druck, zweifelhafter Absender, Forderung nach sensiblen Daten und verdächtiger Link sind die typischen Zeichen. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · gute Praxis gemäss NCSC"},{"k":"qcm","q":"Welches Element verrät in diesem E-Mail am besten einen Phishing-Versuch?","a":["Absender und Link verwenden ungewöhnliche Domains","Die Nachricht ist auf Deutsch und beginnt mit «Lieber Kunde»","Die Adresse des Empfängers endet auf .ch","Der Text der Nachricht enthält einen blauen Knopf"],"img":"mail","ex":"Die Domains «.xyz» und «.top» ohne Bezug zu einem echten Transporteur verraten den Versuch. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · gute Praxis gemäss NCSC"},{"k":"sort","q":"Sicheres oder riskantes Verhalten? Ordnen Sie zu.","c":["Sicher","Riskant"],"it":[["Den Bildschirm sperren, wenn man den Platz verlässt",0],["Einen auf dem Parkplatz gefundenen USB-Stick einstecken",1],["Die von der Informatik freigegebenen Updates installieren",0],["Sein Passwort auf ein Post-it schreiben",1],["Den Absender prüfen, bevor man einen Anhang öffnet",0],["Das Antivirenprogramm deaktivieren, weil es den PC bremst",1]],"ex":"Diese Reflexe ergänzen die Passwortregeln des Kurses. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · gute Praxis gemäss NCSC"},{"k":"match","q":"Ordnen Sie jeder Bedrohung ihre Beschreibung zu.","p":[["Phishing","Gefälschte Nachricht, um Zugangsdaten zu stehlen"],["Virus","Programm, das Dateien befällt und beschädigt"],["Ransomware","Verschlüsselt die Daten und verlangt Lösegeld"],["Hacker","Person, die unberechtigt in ein System eindringt"]],"ex":"Die im Lernziel A2.3 genannten Bedrohungen. (Definitionen nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · gute Praxis gemäss NCSC"},{"k":"order","q":"Sie haben Ihr Passwort auf einer verdächtigen Seite eingegeben. Bringen Sie die Reaktionen in die richtige Reihenfolge.","a":["Auf der offenen Seite nichts mehr eingeben","Sofort die Informatik informieren","Das betroffene Passwort ändern","Das Konto in den folgenden Tagen überwachen"],"ex":"Stoppen, melden, ändern, überwachen: Je schneller die Reaktion, desto kleiner der Schaden. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · gute Praxis gemäss NCSC"},{"k":"case","s":"Ein Kollege wählt als Passwort den Namen seines Hundes, gefolgt von seinem Geburtsjahr.","q":"Welche Regel hält er nicht ein?","a":["Persönliche Angaben vermeiden","Das Passwort jeden Tag wechseln","Nur Ziffern verwenden","Nie Kleinbuchstaben verwenden"],"ex":"Persönliche Angaben (Namen, Daten) sind leicht zu erraten.","ref":"Lektion 9.5.1"},{"k":"case","s":"Um nichts zu vergessen, verwendet eine Lernende dasselbe Passwort für ihre E-Mail, die Lagersoftware und ihr Konto in einem Onlineshop.","q":"Welches Risiko geht sie ein?","a":["Ein Leck auf einer Website öffnet alle ihre Konten","Keines, solange das Passwort über 12 Zeichen hat","Ihr Computer wird durch das viele Anmelden langsamer","Sie kann keine geschäftlichen E-Mails mehr empfangen"],"ex":"Ein eigenes Passwort pro Konto begrenzt den Schaden eines Datenlecks.","ref":"Lektion 9.5.1"},{"k":"case","s":"Ein Kollege hat sein Passwort an den Bildschirm des Bestellerfassungsplatzes geklebt, «für das Nachtteam».","q":"Was raten Sie?","a":["Den Zettel entfernen und einen Zugang pro Benutzer erstellen lassen","Den Zettel in eine abschliessbare Schublade am selben Platz legen","Das Passwort kleiner aufschreiben, damit man es nicht lesen kann","Den Zettel lassen, da er nur dem Nachtteam dient"],"ex":"Jeder Benutzer hat seinen eigenen, nach Verantwortung vergebenen Zugang; ein Passwort wird nicht ausgehängt.","ref":"Lektion 9.5"},{"k":"case","s":"Sie finden auf dem Parkplatz des Betriebs einen USB-Stick mit der Aufschrift «Löhne 2026».","q":"Was tun Sie?","a":["Ihn uneingesteckt der Informatik abgeben","Ihn einstecken, um den Besitzer zu finden","Ihn an einem alten PC im Lager einstecken","Ihn behalten oder in den Abfall werfen"],"ex":"Ein unbekannter USB-Stick kann Schadsoftware enthalten: Man steckt ihn nie ein. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · gute Praxis gemäss NCSC"},{"k":"case","s":"Ein «Microsoft-Techniker» ruft Sie an und verlangt Ihr Passwort, um ein dringendes Problem an Ihrem Arbeitsplatz zu beheben.","q":"Welche Reaktion ist richtig?","a":["Es nie angeben und die Informatik warnen","Es angeben, weil er den Namen des Betriebs kennt","Es nur angeben, wenn er ein zweites Mal anruft","Es lieber per E-Mail als am Telefon schicken"],"ex":"Kein seriöser Dienst verlangt Ihr Passwort. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · gute Praxis gemäss NCSC"},{"k":"case","s":"Die Lagerverwaltungssoftware bietet ein von der Informatik freigegebenes Sicherheitsupdate an.","q":"Warum installiert man es?","a":["Es behebt Lücken, die Hacker ausnutzen könnten","Es macht das Passwort überflüssig","Es hebt die Pflicht zur Datensicherung auf","Es beschleunigt nur den Druck der Etiketten"],"ex":"Updates schliessen Lücken, die Angreifern bekannt sind. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · gute Praxis gemäss NCSC"},{"k":"case","s":"Eines Morgens sind alle Dateien auf dem Server unlesbar, und eine Nachricht verlangt eine Zahlung in Kryptowährung, um sie zurückzuerhalten.","q":"Um welche Art von Angriff handelt es sich?","a":["Eine Ransomware","Ein Brute-Force-Angriff","Ein Druckerausfall","Ein Phishing per SMS"],"ex":"Ransomware verschlüsselt die Daten und verlangt Lösegeld; man alarmiert die Informatik und bezahlt nicht. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · gute Praxis gemäss NCSC"},{"k":"case","s":"Sie müssen Ihren Platz für zehn Minuten verlassen, um an der Verladerampe zu helfen. Ihre Sitzung in der Lagersoftware ist offen.","q":"Was tun Sie?","a":["Den Bildschirm sperren, bevor man geht","Die Sitzung offen lassen, es geht schnell","Nur den Bildschirm ausschalten","Den Chauffeur bitten, den PC zu überwachen"],"ex":"Eine offene Sitzung erlaubt jedem, in Ihrem Namen zu handeln. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · gute Praxis gemäss NCSC"},{"k":"case","s":"Ihr Betrieb aktiviert die Zwei-Faktor-Authentifizierung. Ein Kollege murrt: «Mein Passwort genügt!»","q":"Welches Argument geben Sie ihm?","a":["Auch mit gestohlenem Passwort kann sich ein Hacker nicht anmelden","Er muss danach sein Passwort nie mehr wechseln","Das ersetzt das Antivirenprogramm auf seinem Arbeitscomputer","Das erlaubt ihm, sein Passwort mit dem Team zu teilen"],"ex":"Der zweite Faktor sperrt den Zugang, auch wenn das Passwort bekannt ist.","ref":"Lektion 9.5.1"},{"k":"case","s":"Der Empfang erhält ein E-Mail eines unbekannten Transporteurs: Er verlangt CHF 2.99 innert 24 Stunden, um ein Paket freizugeben, mit einem Knopf «Jetzt bezahlen».","q":"Was ist die richtige Reaktion?","a":["Nicht klicken und das E-Mail der Informatik melden","Die 2.99 Franken bezahlen, der Betrag ist klein","Antworten, um mehr Informationen zu verlangen","Das E-Mail allen Kollegen zur Meinung weiterleiten"],"img":"mail","ex":"Dringlichkeit, kleiner Betrag und Forderung nach Kreditkarte: Das ist Phishing. Man meldet es (in der Schweiz auch dem NCSC). (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · gute Praxis gemäss NCSC"},{"k":"case","s":"Ein SMS teilt Ihnen mit, dass ein Paket auf die Zahlung von «Gebühren von CHF 1.50» wartet, mit einem gekürzten Link.","q":"Wie gehen Sie damit um?","a":["Nicht klicken, die Nachricht löschen oder melden","Auf den Link klicken, um zu prüfen, ob es das Paket gibt","Die Gebühren bezahlen, der Betrag ist wirklich symbolisch","Mit «STOP» antworten, um keine Nachrichten mehr zu erhalten"],"ex":"Phishing gibt es auch per SMS; eine Antwort bestätigt, dass Ihre Nummer aktiv ist. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · gute Praxis gemäss NCSC"}]},{"code":"B1.5","t":"Geheimnisse und Datenschutz","g":"Ich erkläre die Grundlagen und Auswirkungen des Daten- und Persönlichkeitsschutzes sowie des Postgeheimnisses. (K2)","col":"violet","ic":"mailx","ch":[{"k":"qcm","q":"Welcher Artikel des Strafgesetzbuchs bestraft die Verletzung des Schriftgeheimnisses?","a":["Art. 179 StGB","Art. 321ter StGB","Art. 321a Abs. 1 OR","Art. 6 DSG"],"ex":"Art. 179 StGB, unter «Strafbare Handlungen gegen die Ehre und den Geheim- oder Privatbereich».","ref":"Lektion 9.2 · CP 179"},{"k":"qcm","q":"Welcher Artikel des Strafgesetzbuchs bestraft die Verletzung des Postgeheimnisses?","a":["Art. 321ter StGB","Art. 179 StGB","Art. 162 StGB","Art. 321a Abs. 1 OR"],"ex":"Art. 321ter StGB: Verletzung des Post- und Fernmeldegeheimnisses.","ref":"Lektion 9.3 · CP 321ter"},{"k":"qcm","q":"Wo ist das Geschäftsgeheimnis der Arbeitnehmenden laut Kurs geregelt?","a":["Im Obligationenrecht (OR)","Im Strassenverkehrsgesetz","Im internen Reglement der Post","In der Kantonsverfassung"],"ex":"Die Sorgfalts- und Treuepflicht von Art. 321a OR umfasst die Verschwiegenheit über Geschäftsgeheimnisse.","ref":"Lektion 9.4 · CO 321a"},{"k":"tf","q":"Das Schriftgeheimnis gilt nur im beruflichen Bereich.","v":false,"ex":"Es gilt auch im privaten Bereich: Die Post anderer geht auch Privatpersonen nichts an.","ref":"Lektion 9.2"},{"k":"qcm","q":"Was ist ein Antragsdelikt?","a":["Die Behörden ermitteln nur, wenn die geschädigte Person es verlangt","Die Behörden ermitteln, sobald sie von den Tatsachen erfahren","Nur der Arbeitgeber der Täterschaft kann Strafantrag stellen","Das Delikt wird intern vom Betrieb selbst beurteilt"],"ex":"Bei einem Offizialdelikt hingegen müssen die Behörden von sich aus ermitteln.","ref":"Lektion 9.2"},{"k":"match","q":"Ordnen Sie jedem Begriff seine Definition zu.","p":[["Antragsdelikt","Ermittlung auf Antrag der geschädigten Person"],["Offizialdelikt","Ermittlung, sobald die Behörde davon erfährt"],["Schriftgeheimnis","Schützt den Inhalt verschlossener Briefe und Pakete"],["Postgeheimnis","Schützt auch Absender und Empfänger"]],"ex":"Das Postgeheimnis geht über den Inhalt hinaus: Es schützt auch die Identität der Personen und die Häufigkeit der Sendungen.","ref":"Lektionen 9.2 und 9.3"},{"k":"multi","q":"Was schützt das Postgeheimnis?","good":["Den Inhalt der Sendungen","Die Identität des Absenders","Die Identität des Empfängers","Die Häufigkeit der Sendungen"],"bad":["Die offiziellen Tarife der Post","Die öffentliche Adresse einer Poststelle"],"ex":"Das Postgeheimnis verhindert jede Bekanntgabe der Identität der Personen oder der Häufigkeit der Sendungen.","ref":"Lektion 9.3"},{"k":"fill","q":"Das Postgeheimnis geht über die blosse Vertraulichkeit der ___ hinaus.","a":["Briefe","Rechnungen","Briefmarken","Tarife"],"ex":"Es umfasst auch den Schutz von Absender und Empfänger.","ref":"Lektion 9.3"},{"k":"tf","q":"Das Postgeheimnis muss auch nach Ende des Arbeitsverhältnisses gewahrt werden.","v":true,"ex":"Die Verletzung bleibt auch nach Ende des Arbeitsverhältnisses strafbar (Art. 321ter Abs. 3 StGB).","ref":"Lektion 9.3 · CP 321ter"},{"k":"multi","q":"Welche Informationen nennt der Kurs als höchst privat?","good":["Gerichtsurkunden","Zahlungsmitteilungen","Die AHV-Auszahlung"],"bad":["Die Öffnungszeiten eines Lagers","Das Wetter des Tages"],"ex":"Der Kurs nennt diese Beispiele: Gerichtsurkunden, Zahlungsmitteilungen, AHV-Auszahlung.","ref":"Lektion 9.3"},{"k":"qcm","q":"Wie lange muss die Arbeitnehmerin Fabrikations- und Geschäftsgeheimnisse wahren?","a":["Während und nach dem Vertrag, soweit nötig","Nur während der Probezeit, danach entfällt das Geheimnis","Nur während der tatsächlichen Arbeitszeit","Bis Ende des Kalenderjahres, in dem der Vertrag endet"],"ex":"Die Schweigepflicht besteht nach Vertragsende weiter, soweit es die berechtigten Interessen des Arbeitgebers erfordern.","ref":"Lektion 9.4 · CO 321a al. 4"},{"k":"fill","q":"Der Arbeitnehmer hat die übertragene Arbeit sorgfältig auszuführen und die berechtigten Interessen des Arbeitgebers in ___ zu wahren.","a":["guten Treuen","Teilen","Ausnahmefällen","freiem Ermessen"],"ex":"Das ist die Sorgfalts- und Treuepflicht (Art. 321a Abs. 1 OR).","ref":"Lektion 9.4 · CO 321a"},{"k":"sort","q":"Postgeheimnis oder Geschäftsgeheimnis? Ordnen Sie zu.","c":["Postgeheimnis","Geschäftsgeheimnis"],"it":[["Identität des Empfängers eines Einschreibens",0],["Herstellungsrezept eines Produkts",1],["Häufigkeit der Sendungen eines Kunden",0],["Mit Lieferanten ausgehandelte Preise",1],["Inhalt eines beförderten Briefs",0],["Projekt für einen neuen Logistikstandort",1]],"ex":"Das Postgeheimnis schützt die Sendungen und die Personen; das Geschäftsgeheimnis schützt die Informationen des Arbeitgebers.","ref":"Lektionen 9.3 und 9.4"},{"k":"odd","q":"Finden Sie den Ausreisser: Diese Elemente unterstehen einem geschützten Geheimnis, ausser einem.","a":["Die öffentliche Adresse des Firmensitzes","Der Inhalt eines verschlossenen Pakets","Der Absender einer Gerichtsurkunde","Die Handelsmargen des Arbeitgebers"],"ex":"Die Adresse des Sitzes ist öffentlich; die drei anderen sind geschützt (Schriftgeheimnis, Postgeheimnis, Geschäftsgeheimnis).","ref":"Lektionen 9.2 bis 9.4"},{"k":"order","q":"Ein Kollege öffnet unbefugt einen verschlossenen Brief, der für eine andere Person bestimmt ist. Bringen Sie den weiteren Ablauf in die richtige Reihenfolge (Art. 179 StGB).","a":["Der Brief wird unbefugt geöffnet","Der Empfänger entdeckt die Öffnung","Der Empfänger stellt Strafantrag","Die Behörden eröffnen eine Untersuchung","Das Gericht kann eine Busse aussprechen"],"ex":"Es ist ein Antragsdelikt: Ohne Antrag der geschädigten Person keine Ermittlung.","ref":"Lektion 9.2 · CP 179"},{"k":"qcm","q":"Seit wann ist das neue Bundesgesetz über den Datenschutz (revDSG) in Kraft?","a":["Seit dem 1. September 2023","Seit dem 1. Januar 2000","Seit dem 1. Januar 2026","Seit dem 1. Juli 1992"],"ex":"Das totalrevidierte DSG ist am 1. September 2023 ohne Übergangsfrist in Kraft getreten. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · revDSG (in Kraft seit 1.9.2023)"},{"k":"multi","q":"Welches sind Grundsätze der Datenbearbeitung gemäss revDSG?","good":["Rechtmässigkeit","Treu und Glauben","Verhältnismässigkeit","Zweckbindung","Sicherheit"],"bad":["Rentabilität","Werbung"],"ex":"Art. 6 und 8 DSG: Rechtmässigkeit, Treu und Glauben, Verhältnismässigkeit, Zweckbindung, Transparenz, Richtigkeit und Sicherheit. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · revDSG (in Kraft seit 1.9.2023)"},{"k":"tf","q":"Das revDSG schützt die Daten natürlicher Personen, aber nicht mehr jene juristischer Personen (Unternehmen).","v":true,"ex":"Seit 2023 sind nur noch die Daten natürlicher Personen durch das DSG geschützt. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · revDSG (in Kraft seit 1.9.2023)"},{"k":"case","s":"Im internen Postdienst bemerkt eine Kollegin einen Umschlag des Betreibungsamts an einen Kollegen und erzählt in der Pause davon.","q":"Welchen Grundsatz verletzt sie?","a":["Die Verschwiegenheit über Absender und Empfänger","Keinen, da sie den Umschlag nicht geöffnet hat","Nur die Anstandsregeln unter Kollegen","Das Geschäftsgeheimnis des Betreibungsamts"],"ex":"Der Schutz geht über den Inhalt hinaus: Die Identität von Absender und Empfänger wird nicht weitergegeben.","ref":"Lektion 9.3"},{"k":"case","s":"Auf Ihrer Tour bemerken Sie, dass ein Kunde jeden Monat Post der AHV-Ausgleichskasse erhält. Ein Nachbar fragt Sie, ob er eine Rente bezieht.","q":"Was antworten Sie?","a":["Sie geben keine Auskunft über die Post der Kunden","Sie bestätigen, da es kein richtiges Geheimnis ist","Sie antworten nur, wenn der Nachbar auch Ihr Freund ist","Sie raten ihm, selbst in den Briefkasten zu schauen"],"ex":"Der Kurs nennt ausdrücklich die AHV-Auszahlung als vertrauliche Information.","ref":"Lektion 9.3"},{"k":"case","s":"Ihr Mitbewohner öffnet «aus Neugier» einen verschlossenen Brief, der an Sie adressiert ist.","q":"Gilt das Schriftgeheimnis?","a":["Ja, es gilt auch im privaten Bereich","Nein, es betrifft nur Angestellte der Post","Nein, es betrifft nur Pakete","Ja, aber nur für einen Brief eines Gerichts"],"ex":"Das Schriftgeheimnis gilt auch unter Privatpersonen.","ref":"Lektion 9.2 · CP 179"},{"k":"case","s":"Ein ehemaliger Mitarbeiter eines Briefzentrums, der vor zwei Jahren gegangen ist, erzählt, welche Nachbarn Gerichtsurkunden erhalten.","q":"Kann er verfolgt werden?","a":["Ja, die Verletzung bleibt nach der Anstellung strafbar","Nein, das Geheimnis endet mit dem Arbeitsvertrag","Nein, weil er nicht mehr für die Post arbeitet","Nur wenn er die Sendungen selbst geöffnet hat"],"ex":"Das Postgeheimnis gilt auch nach Ende des Arbeitsverhältnisses weiter.","ref":"Lektion 9.3 · CP 321ter"},{"k":"case","s":"Eine Kundin entdeckt, dass ein Mitarbeiter des Empfangs einen verschlossenen Brief an sie geöffnet hat, sie will aber keinen Strafantrag stellen.","q":"Was geschieht strafrechtlich (Art. 179 StGB)?","a":["Nichts: Es ist ein Antragsdelikt","Die Polizei ermittelt sowieso","Der Mitarbeiter kommt automatisch ins Gefängnis","Der Betrieb bezahlt eine feste Busse"],"ex":"Ohne Antrag der geschädigten Person ermitteln die Behörden nicht.","ref":"Lektion 9.2 · CP 179"},{"k":"case","s":"Im Café fragt Sie ein Freund, wie viel Ihr Betrieb seinem grössten Kunden für die Lagerung verrechnet.","q":"Was tun Sie?","a":["Sie lehnen ab: Das ist ein Geschäftsgeheimnis","Sie antworten, da es ein Freund ist","Sie nennen nur eine ungefähre Zahl","Sie antworten, wenn Ihre Probezeit vorbei ist"],"ex":"Die Geschäftsinformationen des Arbeitgebers sind vertraulich (Art. 321a OR).","ref":"Lektion 9.4 · CO 321a"},{"k":"case","s":"Sie wechseln zu einem Konkurrenten. Ihr neuer Chef verlangt die Kundenliste Ihres früheren Arbeitgebers.","q":"Wie reagieren?","a":["Ablehnen: Die Schweigepflicht gilt weiter","Annehmen, der alte Vertrag bindet Sie nicht mehr","Annehmen, wenn die Liste über ein Jahr alt ist","Sie lieber mündlich als schriftlich weitergeben"],"ex":"Die Pflicht, Geschäftsgeheimnisse zu wahren, besteht nach Vertragsende weiter.","ref":"Lektion 9.4 · CO 321a al. 4"},{"k":"case","s":"In einem sozialen Netzwerk veröffentlicht ein Lernender einen langen Beitrag, der seinen Betrieb und seine Vorgesetzten offen kritisiert.","q":"Was empfiehlt der Kurs?","a":["Zurückhaltung zeigen und öffentliche Kritik vermeiden","Öffentlich kritisieren, um schnell etwas zu bewegen","Nur unter einem Pseudonym posten, um diskret zu bleiben","Den Betrieb erwähnen, damit er öffentlich antwortet"],"ex":"Der Kurs empfiehlt Zurückhaltung: Öffentliche Kritik hinterlässt einen schlechten Eindruck.","ref":"Lektion 9.4"},{"k":"case","s":"Ihr Betrieb notiert das Geburtsdatum jeder Person, die das Lager besucht, «für alle Fälle», ohne ihr den Grund zu nennen.","q":"Welche Grundsätze des revDSG sind betroffen?","a":["Verhältnismässigkeit sowie Treu und Glauben","Nur die Rentabilität des Betriebs","Keine, Besuchende sind keine Kunden","Nur das Post- und das Geschäftsgeheimnis"],"ex":"Man erhebt nur die nötigen Daten, für einen für die Person erkennbaren Zweck. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · revDSG (in Kraft seit 1.9.2023)"},{"k":"case","s":"Ein Chauffeur fotografiert einen von einem Kunden unterschriebenen Lieferschein und postet ihn in einem Chat, um sich über die Unterschrift lustig zu machen.","q":"Was ist das Problem?","a":["Er gibt grundlos Personendaten bekannt","Keines, eine Unterschrift ist kein Datum","Nur die Qualität des Fotos ist ein Problem","In einem privaten Chat ist das erlaubt"],"ex":"Name, Adresse und Unterschrift sind Personendaten: Ihre grundlose Verbreitung verletzt die Privatsphäre des Kunden. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · revDSG (in Kraft seit 1.9.2023)"}]},{"code":"B1.6","t":"Folgen in der Praxis","g":"Ich erkläre die Folgen der gesetzlichen Bestimmungen zum Daten- und Persönlichkeitsschutz und zum Postgeheimnis für die praktische Tätigkeit sowie eine Folge für Kunde und Betrieb bei einer Verletzung. (K2)","col":"coral","ic":"balance","ch":[{"k":"pickimg","q":"Der Postdienst darf diesen Umschlag ohne Zögern öffnen. Welchen?","a":["env_a","env_b","env_c","env_d"],"ex":"Nur an den Betrieb adressiert: Er darf geöffnet werden.","ref":"Lektion 9.2 · Tabelle der Adressen"},{"k":"pickimg","q":"Welchen darf der Postdienst NIE öffnen?","a":["env_d","env_a","env_b","env_c"],"ex":"Der Vermerk «Persönlich/vertraulich» verbietet jedes Öffnen.","ref":"Lektion 9.2 · Tabelle der Adressen"},{"k":"pickimg","q":"Welcher wird nur geöffnet, wenn Herr Gugger es ausdrücklich gewünscht hat?","a":["env_c","env_a","env_d"],"ex":"Der Name der Person steht vor dem Betrieb: Man öffnet nur, wenn Herr Gugger es ausdrücklich gewünscht hat.","ref":"Lektion 9.2 · Tabelle der Adressen"},{"k":"pickimg","q":"Welcher darf auf Anweisung geöffnet werden, ohne gegenteiligen Bescheid?","a":["env_b","env_c","env_d"],"ex":"Zuerst der Betrieb, danach «zuhanden von»: Öffnen auf Anweisung, ohne gegenteiligen Bescheid.","ref":"Lektion 9.2 · Tabelle der Adressen"},{"k":"match","q":"Ordnen Sie jedem Umschlag seine Regel für das Öffnen zu.","p":[["A · EnterSite AG","Öffnen"],["B · zuhanden von R. Gugger","Auf Anweisung öffnen, ohne gegenteiligen Bescheid"],["C · Herr Reto Gugger, EnterSite AG","Nur wenn Herr Gugger es gewünscht hat"],["D · Persönlich/vertraulich","Nie öffnen"]],"img":"env","ex":"Je stärker die Person in der Adresse hervorgehoben ist, desto eher gilt die Post als persönlich.","ref":"Lektion 9.2 · Tabelle der Adressen"},{"k":"sort","q":"Darf der Postdienst diese Post öffnen? Ordnen Sie zu.","c":["Darf geöffnet werden","Nicht ohne Einverständnis des Empfängers"],"it":[["Adresse: nur EnterSite AG",0],["EnterSite AG, zuhanden von R. Gugger",0],["Herr R. Gugger, EnterSite AG",1],["Vermerk «Persönlich/vertraulich»",1]],"img":"env","ex":"A und B dürfen geöffnet werden (B auf Anweisung); C nur, wenn Herr Gugger es gewünscht hat; D nie.","ref":"Lektion 9.2 · Tabelle der Adressen"},{"k":"tf","q":"Steht der Name der Person vor dem Namen des Betriebs, gilt der Brief als persönlich.","v":true,"ex":"«Herr Reto Gugger, EnterSite AG»: Man öffnet nur, wenn Herr Gugger es ausdrücklich gewünscht hat.","ref":"Lektion 9.2 · Tabelle der Adressen"},{"k":"tf","q":"Das Schriftgeheimnis betrifft auch die Mitarbeitenden eines internen Postdienstes im Betrieb.","v":true,"ex":"Der Inhalt der Briefe und Pakete geht sie nichts an, genauso wenig wie die Angestellten der Post.","ref":"Lektion 9.2"},{"k":"qcm","q":"Welche Strafe sieht Art. 179 StGB für die Verletzung des Schriftgeheimnisses vor?","a":["Eine Busse, auf Antrag","Eine Freiheitsstrafe von zehn Jahren","Eine blosse mündliche Verwarnung","Keine, es ist eine moralische Regel"],"ex":"Art. 179 StGB: «wird, auf Antrag, mit Busse bestraft».","ref":"Lektion 9.2 · CP 179"},{"k":"qcm","q":"Was riskiert ein Angestellter eines Postdienstes, der das Postgeheimnis verletzt?","a":["Eine Freiheitsstrafe oder eine Geldstrafe","Nur einen schriftlichen Verweis seines Dienstchefs","Eine Ordnungsbusse von 20 Franken, sofort zahlbar","Gar nichts, wenn er die Stelle inzwischen verlassen hat"],"ex":"Der Kurs spricht von Freiheits- oder Geldstrafen, auch nach Ende des Arbeitsverhältnisses (Art. 321ter StGB).","ref":"Lektion 9.3 · CP 321ter"},{"k":"num","q":"Höchste Freiheitsstrafe in Jahren gemäss Art. 321ter StGB?","n":3,"tol":0,"u":"Jahre","ex":"Art. 321ter Abs. 1 StGB: Freiheitsstrafe bis zu drei Jahren oder Geldstrafe. (Zahl nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · StGB 321ter Abs. 1"},{"k":"num","q":"Höchstbetrag der Busse in Franken, die das revDSG für gewisse vorsätzliche Verletzungen vorsieht?","n":250000,"tol":0,"u":"CHF","ex":"Das revDSG sieht Bussen bis CHF 250 000 vor, die der verantwortlichen Person auferlegt werden. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · revDSG (in Kraft seit 1.9.2023)"},{"k":"qcm","q":"Was kann der Arbeitgeber laut Kurs gegen einen Arbeitnehmer tun, der Geschäftsgeheimnisse nicht wahrt?","a":["Ihn anzeigen","Ihm das Stimmrecht entziehen","Ihm die gesetzlichen Ferien streichen","Nichts, das Gesetz sieht es nicht vor"],"ex":"Wer diese Regel nicht einhält, kann vom Arbeitgeber angezeigt werden.","ref":"Lektion 9.4"},{"k":"multi","q":"Welche Folgen kann eine Verletzung des Datenschutzes für den Betrieb haben?","good":["Vertrauensverlust bei den Kunden","Schaden für sein Image","Strafantrag oder Strafe","Verlust von Kunden oder Aufträgen"],"bad":["Automatischer Anstieg seiner Verkäufe"],"ex":"Vertrauen steht im Zentrum der Logistik: Ein Leck zerstört es schnell.","ref":"Lernziel B1.6"},{"k":"multi","q":"Welche Folgen hat es für den Kunden, dessen Daten bekannt gegeben wurden?","good":["Verletzung seiner Privatsphäre","Bekanntgabe sensibler Informationen (Betreibungen, Geld)","Gefahr von Betrug oder Identitätsdiebstahl"],"bad":["Senkung seiner Steuern","Schnellere Lieferung seiner Pakete"],"ex":"Der Kurs erinnert daran, dass schwache Passwörter Betrug und Identitätsdiebstahl begünstigen; eine Bekanntgabe trifft die Privatsphäre.","ref":"Lektionen 9.3 und 9.5"},{"k":"odd","q":"Finden Sie den Ausreisser: Diese Handlungen wahren das Geheimnis im Alltag, ausser einer.","a":["Die Post eines Kunden mit einem Nachbarn besprechen","Einen verschlossenen Brief ungelesen übergeben","Ausserhalb der Arbeit nicht über Kunden reden","Einen vertraulichen Brief ungeöffnet weitergeben"],"ex":"Die Post der Kunden wird nie mit Dritten besprochen.","ref":"Lektion 9.3"},{"k":"order","q":"Ein Umschlag «Persönlich/vertraulich» wurde im internen Postdienst irrtümlich geöffnet. Bringen Sie die Handlungen in die richtige Reihenfolge.","a":["Sofort mit Lesen aufhören","Wieder verschliessen und «irrtümlich geöffnet» vermerken","Die Sendung dem Empfänger mit einer Information übergeben"],"ex":"Man begrenzt die Kenntnisnahme, meldet den Fehler und übergibt die Sendung. (Gute Praxis, nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · gute Praxis"},{"k":"case","s":"Im Postdienst der EnterSite AG sortieren Sie einen Brief an «Herr Reto Gugger, EnterSite AG». Herr Gugger hat keine Anweisung gegeben.","q":"Was tun Sie?","a":["Sie leiten ihn verschlossen an ihn weiter","Sie öffnen ihn, um ihn der richtigen Abteilung zuzuteilen","Sie öffnen ihn und verschliessen ihn danach sorgfältig","Sie schicken ihn an den Absender zurück"],"img":"env","ex":"Umschlag C: Man öffnet nur, wenn Herr Gugger es ausdrücklich gewünscht hat.","ref":"Lektion 9.2 · Tabelle der Adressen"},{"k":"case","s":"Ihre Chefin hat Sie gebeten, während ihrer Ferien die Post des Betriebs zu öffnen. Ein Brief «Persönlich/vertraulich» ist an sie adressiert.","q":"Was tun Sie?","a":["Sie lassen ihn bis zu ihrer Rückkehr verschlossen","Sie öffnen ihn, da sie Sie darum gebeten hat","Sie lassen ihn von einem Kollegen öffnen","Sie lesen ihn, ohne ihn aus dem Umschlag zu nehmen"],"ex":"«Persönlich/vertraulich»: nie öffnen. Die Anweisung betrifft die Post des Betriebs.","ref":"Lektion 9.2 · Tabelle der Adressen"},{"k":"case","s":"Ein Brief kommt an mit der Adresse «EnterSite AG, zuhanden von Reto Gugger». Es gibt keine gegenteilige Anweisung.","q":"Was tun gemäss der Tabelle im Kurs?","a":["Er darf auf Anweisung geöffnet werden","Er darf nie geöffnet werden","Nur wenn Herr Gugger es gewünscht hat","Ihn an den Absender zurückschicken"],"ex":"Umschlag B: Ohne gegenteiligen Bescheid wird er auf Anweisung geöffnet.","ref":"Lektion 9.2 · Tabelle der Adressen"},{"k":"case","s":"Ein Kurier erzählt im Restaurant, dass ein Kunde viele Einschreiben des Betreibungsamts erhält. Der Kunde erfährt es.","q":"Welche Folge hat das für den Kunden?","a":["Seine Finanzlage wird offengelegt","Keine, Einschreiben sind nicht vertraulich","Er erhält einen Zahlungsaufschub","Seine Betreibungen werden aufgehoben"],"ex":"Das Postgeheimnis schützt genau die Identität des Absenders und die Gerichtsurkunden.","ref":"Lektion 9.3"},{"k":"case","s":"Ein Kunde entdeckt, dass ein Kurier seine Sendungen des Betreibungsamts ausgeplaudert hat, und erzählt die Sache in den sozialen Netzwerken.","q":"Welche Folge riskiert das Lieferunternehmen?","a":["Vertrauensverlust, Imageschaden, Abwanderung von Kunden","Mehr Aufträge dank der kostenlosen Werbung","Keine, denn nur der Kurier ist von der Sache betroffen","Eine öffentliche Subvention, um den Kurier besser auszubilden"],"ex":"Der Betrieb erleidet einen Vertrauensverlust, zusätzlich zum Verfahren gegen den Mitarbeiter.","ref":"Lernziel B1.6"},{"k":"case","s":"Ein Büroangestellter eines Bauunternehmens öffnet aus Neugier ein verschlossenes Paket an einen Kollegen.","q":"Welcher Artikel kann angewendet werden?","a":["Art. 179 StGB, Schriftgeheimnis","Art. 321a OR, Treue des Kunden","Art. 162 StGB, Fabrikationsgeheimnis","Keiner, unter Kollegen ist das erlaubt"],"ex":"Unbefugt einen verschlossenen Brief oder ein Paket öffnen, um den Inhalt zu erfahren: Art. 179 StGB.","ref":"Lektion 9.2 · CP 179"},{"k":"case","s":"Eine Angestellte der Post erzählt ihrer Familie, dass ein Nachbar regelmässig Sendungen einer Klinik erhält.","q":"Welches strafrechtliche Risiko geht sie ein?","a":["Eine Freiheits- oder Geldstrafe (Art. 321ter StGB)","Eine blosse Ordnungsbusse von 40 Franken (Art. 179 StGB)","Kein Risiko, da sie keine Sendung geöffnet hat","Nur eine interne Verwarnung durch ihren Arbeitgeber"],"ex":"Angaben über den Postverkehr eines Kunden weiterzugeben genügt, auch ohne die Sendung zu öffnen.","ref":"Lektion 9.3 · CP 321ter"},{"k":"case","s":"Ein Lagermitarbeiter gibt einem Konkurrenten die von seinem Arbeitgeber ausgehandelten Einkaufspreise weiter.","q":"Welche Folge ist möglich?","a":["Sein Arbeitgeber kann ihn anzeigen","Keine, Einkaufspreise sind öffentlich","Er erhält eine Prämie seines Arbeitgebers","Nur der Konkurrent ist strafbar"],"ex":"Verletzung des Geschäftsgeheimnisses (Art. 321a OR): Der Arbeitgeber kann ihn anzeigen.","ref":"Lektion 9.4"},{"k":"case","s":"Bei einer Besichtigung des Lagers fotografieren Schüler einen Bildschirm mit Namen, Adressen und Bestellungen von Kunden.","q":"Welche praktische Massnahme hätte das Problem verhindert?","a":["Bildschirme mit Kundendaten abdecken oder sperren","Ab sofort jede Besichtigung des Betriebs verbieten","Die Daten auf den Bildschirmen kleiner anzeigen","Nichts, denn das sind keine Personendaten"],"ex":"Datensicherheit beginnt mit einfachen Handgriffen am Arbeitsplatz. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · revDSG (in Kraft seit 1.9.2023)"},{"k":"case","s":"Ein Kollege wirft Lieferscheine mit Namen, Adressen und Unterschriften von Kunden in den für alle zugänglichen Abfalleimer an der Rampe.","q":"Was sagen Sie ihm?","a":["Diese Dokumente werden sicher vernichtet (Aktenvernichter)","Das ist in Ordnung, es sind alte, wertlose Dokumente","Man muss sie mit dem gewöhnlichen Karton der Rampe rezyklieren","Es genügt, sie vor dem Wegwerfen einmal zu falten"],"ex":"Personendaten werden sicher vernichtet, wenn sie nicht mehr gebraucht werden. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · revDSG (in Kraft seit 1.9.2023)"}]},{"code":"D5.3","t":"Empfangsberechtigte Personen","g":"Ich erkläre die gesetzlichen Rahmenbedingungen zu den Personen, die berechtigt sind, zuzustellende Waren entgegenzunehmen. (K2)","col":"amber","ic":"parcel","ch":[{"k":"qcm","q":"Wem übergibt die Logistikerin die gelieferte Ware?","a":["Einer zum Empfang berechtigten Person","Der ersten Person, die an der Adresse anwesend ist","Irgendeinem verfügbaren Nachbarn","Dem nächsten Chauffeur der Tour"],"ex":"Kompetenz d5: Waren fachgerecht einer berechtigten Person übergeben.","ref":"Bildungsplan · Kompetenz d5"},{"k":"tf","q":"Eine Person im selben Haushalt darf eine gewöhnliche Sendung ohne Vollmacht abholen.","v":true,"ex":"Personen im selben Haushalt brauchen keine Vollmacht (ausser bei Betreibungsurkunden). (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"tf","q":"Eine Person im selben Haushalt darf eine Betreibungsurkunde ohne Vollmacht abholen.","v":false,"ex":"Für Betreibungsurkunden ist immer eine Vollmacht nötig. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"qcm","q":"Was ist eine Postvollmacht?","a":["Eine Berechtigung für eine andere Person, Sendungen abzuholen","Eine Rechnung für eine verspätet zugestellte Sendung","Eine Zusatzversicherung gegen den Verlust eines Pakets","Ein Reklamationsformular für eine beschädigte Sendung"],"ex":"Mit einer Vollmacht berechtigen Sie eine oder mehrere Personen, Ihre Sendungen abzuholen. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"match","q":"Ordnen Sie jeder Situation ihre Regel zu.","p":[["Einzelvollmacht","Für eine bestimmte Sendung"],["Dauervollmacht","Für mehrere Sendungen über längere Zeit"],["Eigenhändig","Keine Vollmacht möglich"],["Gleicher Haushalt","Ohne Vollmacht, ausser Betreibungen"]],"ex":"Regeln der Schweizerischen Post. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"qcm","q":"Welche Art von Vollmacht muss ein Geschäftskunde bei der Post verwenden?","a":["Eine Dauervollmacht","Eine Einzelvollmacht per Telefon","Keine, der Name des Betriebs genügt","Ein einfaches E-Mail des Direktors"],"ex":"Geschäftskunden arbeiten mit einer Dauervollmacht. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"multi","q":"Welche Ausweise werden für die Abholung einer Sendung mit Vollmacht akzeptiert?","good":["Pass","Identitätskarte","Schweizer Führerausweis","Ausländerausweis"],"bad":["Familienbüchlein","Fotokopie der Identitätskarte"],"ex":"Original eines Ausweises mit Foto; das Familienbüchlein wird nicht akzeptiert. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"tf","q":"Eine Fotokopie der Identitätskarte genügt, um ein Einschreiben mit Vollmacht abzuholen.","v":false,"ex":"Man muss das Original eines Ausweises mit Foto vorweisen. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"fill","q":"Eine Sendung «Eigenhändig» muss von der Empfängerin oder dem Empfänger ___ abgeholt werden.","a":["persönlich","per Vollmacht","durch Nachbarn","durch die Familie"],"ex":"Für die eigenhändige Zustellung kann keine Vollmacht erteilt werden. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"sort","q":"Braucht es eine Vollmacht? Ordnen Sie zu.","c":["Ohne Vollmacht","Vollmacht nötig","Unmöglich, auch mit Vollmacht"],"it":[["Ehepartner im Haushalt, gewöhnliches Paket",0],["Freund, eingeschriebener Brief",1],["Kollegin, Sendung «Eigenhändig»",2],["Sohn im Haushalt, Betreibungsurkunde",1],["Nachbar, Paket Signature",1]],"ex":"Haushalt: frei ausser Betreibungen; Dritte: Vollmacht; eigenhändig: nur Empfänger. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"qcm","q":"Was bestätigt die Unterschrift der Person, die ein Einschreiben entgegennimmt?","a":["Die Übergabe der Sendung","Die Bezahlung des Portos","Das Öffnen der Sendung","Das Einverständnis mit dem Inhalt des Briefs"],"ex":"Bevollmächtigte bestätigen den Empfang mit ihrer Unterschrift. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"odd","q":"Finden Sie den Ausreisser: Diese Personen dürfen für Sie am Schalter ein gewöhnliches Paket entgegennehmen, ausser einer.","a":["Ein Passant, der anbietet, es mitzunehmen","Ihr Ehepartner, der mit Ihnen lebt","Eine Person mit Ihrer Dauervollmacht","Eine Person mit einer Einzelvollmacht"],"ex":"Ohne Haushaltsbeziehung oder Vollmacht ist niemand berechtigt. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"order","q":"Abholung eines Einschreibens durch eine bevollmächtigte Person am Schalter: Bringen Sie die Schritte in die richtige Reihenfolge.","a":["Abholungseinladung und Vollmacht vorweisen","Das Original eines Ausweises mit Foto zeigen","Kontrolle der Identität und der Vollmacht","Unterschrift der bevollmächtigten Person","Übergabe der Sendung"],"ex":"Die Identität wird geprüft, dann beweist die Unterschrift die Übergabe. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"qcm","q":"Warum prüft man bei einem Paket Signature oder einem Einschreiben die Identität?","a":["Um die richtige Übergabe zu beweisen","Um die Statistik der Tour zu ergänzen","Um zusätzliche Gebühren einzuziehen","Um das Alter des Kunden zu prüfen"],"ex":"Empfänger oder Bevollmächtigte müssen sich ausweisen. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"tf","q":"Eine Liegenschaftsverwaltung mit Hauswartdienst darf dank ihrer Vollmacht die Gerichtsurkunden der Mietenden entgegennehmen.","v":false,"ex":"Die Vollmacht für Dienstleister schliesst Gerichtsurkunden, Betreibungen und eigenhändige Sendungen aus. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"qcm","q":"Wann ist eine Verletzung des Postgeheimnisses gemäss Art. 321ter StGB nicht strafbar?","a":["Wenn sie nötig ist, um den Berechtigten zu ermitteln","Wenn die Sendung einen geringen Warenwert hat","Wenn der Empfänger bei der Zustellung abwesend ist","Wenn der Kurier am Ende der Tour in Eile ist"],"ex":"Abs. 4: nicht strafbar, wenn nötig, um den Berechtigten zu ermitteln oder einen Schaden zu verhüten. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · StGB 321ter Abs. 4"},{"k":"case","s":"Sie stellen ein Paket Signature zu. Der Empfänger ist abwesend; sein Nachbar bietet an, ohne Vollmacht an seiner Stelle zu unterschreiben.","q":"Was tun Sie?","a":["Sie hinterlassen eine Abholungseinladung","Sie übergeben es, der Nachbar kennt ihn gut","Sie unterschreiben selbst anstelle des Kunden","Sie legen es einfach vor die Haustür"],"ex":"Der Nachbar ist nicht berechtigt: Die Sendung wartet auf den Empfänger oder seine bevollmächtigte Person. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"case","s":"Eine Frau will am Schalter einen eingeschriebenen Brief an ihren Mann abholen, mit dem sie zusammenlebt. Es ist keine Betreibungsurkunde.","q":"Darf sie ihn abholen?","a":["Ja, im gleichen Haushalt ohne Vollmacht","Nein, nur der Mann darf ein Einschreiben abholen","Ja, aber nur mit einer Dauervollmacht","Nein, ausser sie bezahlt eine Gebühr"],"ex":"Gleicher Haushalt: keine Vollmacht, ausser für Betreibungsurkunden. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"case","s":"Ein Mann will ohne Vollmacht einen Zahlungsbefehl an seinen Bruder abholen, mit dem er zusammenwohnt.","q":"Welche Antwort ist richtig?","a":["Ablehnen: Für Betreibungen braucht es eine Vollmacht","Annehmen, da beide im gleichen Haushalt leben","Annehmen, wenn er das Original seiner Identitätskarte zeigt","Annehmen, wenn er verspricht, ihn noch am Abend weiterzugeben"],"ex":"Ausnahme beim Haushalt: Betreibungsurkunden verlangen immer eine Vollmacht. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"case","s":"Ihr Logistikunternehmen will, dass der Rampenchef jeden Tag in der Filiale die an den Betrieb adressierten Sendungen abholt.","q":"Welche Lösung wählen?","a":["Eine Dauervollmacht auf seinen Namen ausstellen","Ihm eine Einzelvollmacht per Telefon geben","Nichts, die Uniform des Betriebs genügt","Ihm die Identitätskarte des Direktors geben"],"ex":"Für einen Geschäftskunden und regelmässige Abholungen: Dauervollmacht. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"case","s":"Um ein Paket mit Vollmacht abzuholen, zeigt ein Kunde ein Foto seiner Identitätskarte auf dem Handy.","q":"Was tun Sie?","a":["Das Original eines Ausweises mit Foto verlangen","Annehmen, denn das Foto auf dem Handy ist gut lesbar","Annehmen, da die Vollmacht korrekt unterschrieben ist","Stattdessen das Original des Familienbüchleins verlangen"],"ex":"Nur das Original eines Ausweises mit Foto wird akzeptiert. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"case","s":"Eine Sendung trägt den Vermerk «Eigenhändig». Die Empfängerin schickt ihren Assistenten mit einer Dauervollmacht.","q":"Darf der Assistent die Sendung abholen?","a":["Nein, «Eigenhändig» schliesst jede Vollmacht aus","Ja, die Dauervollmacht deckt alle Sendungen ab","Ja, wenn er seine eigene Identitätskarte im Original zeigt","Ja, sofern er die Quittung zweimal unterschreibt"],"ex":"Bei eigenhändiger Zustellung muss der Empfänger selbst kommen. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"case","s":"Bei einer Lieferung in einem Betrieb bietet die Empfangsmitarbeiterin an, für ein an den Betrieb adressiertes Paket zu unterschreiben.","q":"Ist das annehmbar?","a":["Ja, wenn der Betrieb sie zum Warenempfang berechtigt hat","Nein, nur der Direktor des Betriebs darf unterschreiben","Nein, ein Betrieb darf kein Paket Signature erhalten","Ja, jede am Empfang anwesende Besucherin darf unterschreiben"],"ex":"In einem Betrieb wird die Ware einer vom Betrieb berechtigten Person übergeben.","ref":"Bildungsplan · Kompetenz d5"},{"k":"case","s":"Ein eiliger Kurier legt ein Paket Signature vor die Tür und bestätigt selbst auf dem Terminal.","q":"Welches Risiko schafft er?","a":["Die Übergabe ist nicht bewiesen, das Paket kann verschwinden","Keines, der Kunde spart Zeit und wird zufrieden sein","Das Paket Signature wird dadurch zu einer gewöhnlichen Sendung","Nur der Empfänger ist für sein Paket verantwortlich"],"ex":"Die Unterschrift beweist die Übergabe an die richtige Person; ohne sie sind Kurier und Betrieb exponiert.","ref":"Bildungsplan · Kompetenz d5"},{"k":"case","s":"Bei der Zustellung eines Einschreibens gibt eine Person an, die Empfängerin zu sein, aber der Name auf ihrem Ausweis stimmt nicht überein.","q":"Was tun Sie?","a":["Nicht übergeben und Abholungseinladung hinterlassen","Sie übergeben, da sie den Inhalt der Sendung kennt","Sie gegen Unterschrift und Trinkgeld übergeben","Die Sendung vor ihr öffnen, um den Inhalt zu prüfen"],"ex":"Die Identität muss nachgewiesen werden: Im Zweifel keine Übergabe. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"},{"k":"case","s":"Ein Kunde möchte, dass seine Nachbarin während seiner Ferien ein einziges Paket in der Filiale abholt.","q":"Welche Vollmacht passt am besten?","a":["Eine Einzelvollmacht für diese Sendung","Eine kostenpflichtige Dauervollmacht","Keine, die Nachbarin darf es frei abholen","Eine eigenhändige Zustellung"],"ex":"Die Einzelvollmacht deckt eine bestimmte Sendung ab; für Privatpersonen ist sie gratis. (Nicht im Kursmaterial.)","ref":"Nicht im Kursmaterial · Post CH, «Vollmacht bei der Post»"}]}];
